import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Explicit-Categories.md","filePath":"manual-en/CTABLES-Explicit-Categories.md","lastUpdated":1785684581000}'),r={name:"manual-en/CTABLES-Explicit-Categories.md"};function i(s,e,c,n,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h4 id="_15-7-5-1-explicit-categories" tabindex="-1">15.7.5.1 Explicit Categories <a class="header-anchor" href="#_15-7-5-1-explicit-categories" aria-label="Permalink to &quot;15.7.5.1 Explicit Categories&quot;">​</a></h4><p>To use <code>CTABLES</code> to explicitly specify categories to include, list the categories within square brackets in the desired sort order. Use spaces or commas to separate values. Categories not covered by the list are excluded from analysis.</p><p>Each element of the list takes one of the following forms:</p><p><code>_number_</code><code>&#39;_string_ &#39;</code></p><p>A numeric or string category value, for variables that have the corresponding type.</p><p><code>&#39;_date_ &#39;</code><code>&#39;_time_ &#39;</code></p><p>A date or time category value, for variables that have a date or time print format.</p><p><code>_min_ THRU _max_</code><code>LO THRU _max_</code><code>_min_ THRU HI</code></p><p>A range of category values, where min and max each takes one of the forms above, in increasing order.</p><p><code>MISSING</code></p><p>All user-missing values. (To match individual user-missing values, specify their category values.)</p><p><code>OTHERNM</code></p><p>Any non-missing value not covered by any other element of the list (regardless of where <code>OTHERNM</code> is placed in the list).</p><p><code>&amp;_postcompute_</code></p><p>A computed category name (see <a href="./CTABLES-Computed-Categories">CTABLES Computed Categories</a>).</p><p><code>SUBTOTAL</code><code>HSUBTOTAL</code></p><p>A subtotal (see <a href="./CTABLES-Totals-and-Subtotals">CTABLES Totals and Subtotals</a>).</p><p>If multiple elements of the list cover a given category, the last one in the list takes precedence.</p><p>The following example syntax and output show how an explicit category can limit the displayed categories:</p><pre><code>CTABLES /TABLE freqOfDriving.
CTABLES /TABLE freqOfDriving /CATEGORIES VARIABLES=freqOfDriving [1, 2, 3].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td></td><td></td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr></tbody></table>`,21)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
